{
  "components": [
    {
      "type": "claim",
      "quote": "Sectoral planning is the federal government’s overlying planning and coordination tool for implementing its spatial planning duties.",
      "gist": "Sectoral planning is the federal government's main tool for spatial planning duties."
    },
    {
      "type": "claim",
      "quote": "Projects concerning the construction and expansion of high-voltage power lines at the 220/380 kV level which have a significant spatial and environmental impact normally have to be specified in the Transmission Lines sectoral plan.",
      "gist": "High-voltage power line projects with significant spatial and environmental impact must be included in the Transmission Lines sectoral plan."
    },
    {
      "type": "entity",
      "quote": "Swiss Federal Office of Energy (SFOE)",
      "gist": "Swiss Federal Office of Energy"
    },
    {
      "type": "entity",
      "quote": "Federal Office for Spatial Development (ARE)",
      "gist": "Federal Office for Spatial Development"
    },
    {
      "type": "entity",
      "quote": "Federal Council",
      "gist": "Federal Council"
    },
    {
      "type": "obligation",
      "quote": "The Swiss Federal Office of Energy (SFOE) is responsible for processing this sectoral plan in cooperation with the Federal Office for Spatial Development (ARE), while the Federal Council is responsible for the detailed specifications.",
      "gist": "SFOE and ARE must process the sectoral plan; Federal Council sets detailed specifications."
    }
  ]
}
